{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Absolute bioavailability of tolfenamic acid averaged 60% in healthy volunteers after oral capsules versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Absolute bioavailability of esaxerenone was approximately 90% after a single 5 mg oral dose in healthy Japanese subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Median absolute oral bioavailability of isradipine was 16% in healthy subjects, below the 20% threshold, arguing against high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred absolute bioavailability records in healthy/ordinary conditions are well above 20% (e.g., 60%, 89%, 90%, 77%), while only isradipine clearly falls below 20%; nilotinib is mixed. High is therefore better supported.",
  "evidence_gaps": [
    "Molecule 7 and Molecule 10 provide only qualitative 'good/high' bioavailability without numeric F values.",
    "Nilotinib evidence is mixed, with values around 17% and around 30%, straddling the 20% threshold.",
    "Isradipine provides a clear contradictory low-F example, but it is a single molecule among several high-F transfers."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

